-- Preserve existing installations; do not edit V1 or discard readings.
ALTER TABLE readings RENAME TO sensor_readings;
UPDATE motion_readings SET ax=ax/9.80665, ay=ay/9.80665, az=az/9.80665;
ALTER TABLE motion_readings ADD COLUMN pitch DOUBLE;
ALTER TABLE motion_readings ADD COLUMN roll DOUBLE;
ALTER TABLE motion_readings ADD COLUMN magnitude DOUBLE;
ALTER TABLE motion_readings ADD COLUMN temperature DOUBLE;
ALTER TABLE motion_readings ADD COLUMN fall_state VARCHAR(80) NOT NULL DEFAULT 'NORMAL';
ALTER TABLE motion_readings ADD COLUMN quality VARCHAR(80) NOT NULL DEFAULT 'UNAVAILABLE';
ALTER TABLE motion_readings ADD COLUMN calibration VARCHAR(80) NOT NULL DEFAULT 'UNVERIFIED';
ALTER TABLE motion_readings ADD COLUMN event_id BIGINT;
ALTER TABLE motion_readings ADD COLUMN impact_count BIGINT;
ALTER TABLE motion_readings ADD COLUMN impact BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE motion_readings ADD COLUMN inactive BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE motion_readings ADD COLUMN acceleration_unit VARCHAR(80) NOT NULL DEFAULT 'g';
UPDATE motion_readings SET magnitude=SQRT(ax*ax+ay*ay+az*az),quality='GOOD' WHERE ax IS NOT NULL AND ay IS NOT NULL AND az IS NOT NULL;
UPDATE motion_readings SET fall_state='POSSIBLE_FALL' WHERE possible_fall=TRUE;
ALTER TABLE gps_locations ADD COLUMN connected BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE gps_locations ADD COLUMN status VARCHAR(80) NOT NULL DEFAULT 'UNKNOWN';
ALTER TABLE gps_locations ADD COLUMN altitude DOUBLE;
ALTER TABLE gps_locations ADD COLUMN characters BIGINT;
ALTER TABLE gps_locations ADD COLUMN passed_checksum BIGINT;
ALTER TABLE gps_locations ADD COLUMN failed_checksum BIGINT;
ALTER TABLE gps_locations ADD COLUMN last_valid_fix_at TIMESTAMP(6);
ALTER TABLE gps_locations ADD COLUMN last_fix_age_ms BIGINT;
ALTER TABLE gps_locations ADD COLUMN stale BOOLEAN NOT NULL DEFAULT TRUE;
UPDATE gps_locations SET connected=TRUE,status='FIX',stale=FALSE,last_valid_fix_at=gps_time WHERE fix=TRUE;
ALTER TABLE sensor_readings ADD COLUMN uptime_ms BIGINT;
CREATE TABLE device_settings(id BIGINT AUTO_INCREMENT PRIMARY KEY,device_id BIGINT NOT NULL UNIQUE,sensitivity DOUBLE NOT NULL DEFAULT 1,impact_g DOUBLE NOT NULL DEFAULT 2.5,low_g DOUBLE NOT NULL DEFAULT 0.6,inactivity_ms BIGINT NOT NULL DEFAULT 2000,cooldown_ms BIGINT NOT NULL DEFAULT 20000,cancel_version BIGINT NOT NULL DEFAULT 0,calibrate_version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(device_id) REFERENCES devices(id),CHECK(sensitivity BETWEEN 0.5 AND 2),CHECK(impact_g BETWEEN 2 AND 6));
INSERT INTO device_settings(device_id) SELECT id FROM devices;
CREATE TABLE alert_acknowledgements(id BIGINT AUTO_INCREMENT PRIMARY KEY,alert_id BIGINT NOT NULL UNIQUE,user_id BIGINT NOT NULL,acknowledged_at TIMESTAMP(6) NOT NULL,FOREIGN KEY(alert_id) REFERENCES alerts(id),FOREIGN KEY(user_id) REFERENCES users(id));
INSERT INTO alert_acknowledgements(alert_id,user_id,acknowledged_at) SELECT id,acknowledged_by,acknowledged_at FROM alerts WHERE acknowledged_by IS NOT NULL AND acknowledged_at IS NOT NULL;
CREATE INDEX ix_motion_state ON motion_readings(fall_state);
ALTER TABLE alerts ADD COLUMN event_key VARCHAR(255);
CREATE UNIQUE INDEX uq_alert_event ON alerts(device_id,event_key);
